94	{
95	  struct spi_dev_s dev;
96	  FAR bk7258_spi_hw_t *hw;   /* SPI1 register block */
97	  mutex_t lock;              /* Mutual exclusion */
98	  uint32_t frequency;        /* Requested frequency */
99	  uint32_t actual;           /* Achieved frequency */
100	  uint8_t mode;              /* Current SPI mode */
101	  uint8_t nbits;             /* Current bit width (8 only) */
102	};
