156	
157	static int bk7258_spi_lock(FAR struct spi_dev_s *dev, bool lock)
158	{
159	  FAR struct bk7258_spi_dev_s *priv = (FAR struct bk7258_spi_dev_s *)dev;
160	  int ret;
161	
162	  if (lock)
163	    {
164	      ret = nxmutex_lock(&priv->lock);
165	    }
166	  else
167	    {
168	      ret = nxmutex_unlock(&priv->lock);
169	    }
170	
171	  return ret;
172	}
173	
174	static void bk7258_spi_select(FAR struct spi_dev_s *dev, uint32_t devid,
175	                              bool selected)
176	{
177	  /* Active-low chip select driven by GPIO3 */
178	
179	  bk7258_gpio_write(BOARD_LCD_CS_PIN, !selected);
180	}
181	
182	static uint32_t bk7258_spi_setfrequency(FAR struct spi_dev_s *dev,
183	                                        uint32_t frequency)
184	{
185	  FAR struct bk7258_spi_dev_s *priv = (FAR struct bk7258_spi_dev_s *)dev;
186	  uint32_t clk_rate;
187	
188	  if (frequency > BK7258_SPI1_MAX_BAUD)
189	    {
190	      frequency = BK7258_SPI1_MAX_BAUD;
191	    }
192	
193	  /* baud = f_src / (2 * clk_rate), round up to stay below the request */
194	
195	  clk_rate = (BK7258_SPI1_SRC_CLK + (2 * frequency) - 1) / (2 * frequency);
196	  if (clk_rate < 1)
197	    {
198	      clk_rate = 1;
199	    }
200	  else if (clk_rate > 0xff)
201	    {
202	      clk_rate = 0xff;
203	    }
204	
205	  priv->hw->ctrl.clk_rate = clk_rate;
206	
207	  priv->frequency = frequency;
208	  priv->actual    = BK7258_SPI1_SRC_CLK / (2 * clk_rate);
209	
210	  return priv->actual;
211	}
212	
213	static void bk7258_spi_setmode(FAR struct spi_dev_s *dev,
214	                               enum spi_mode_e mode)
215	{
216	  FAR struct bk7258_spi_dev_s *priv = (FAR struct bk7258_spi_dev_s *)dev;
217	
218	  switch (mode)
219	    {
220	      case SPIDEV_MODE0: /* CPOL=0 CPHA=0 */
221	        priv->hw->ctrl.cpol = 0;
222	        priv->hw->ctrl.cpha = 0;
223	        break;
224	
225	      case SPIDEV_MODE1: /* CPOL=0 CPHA=1 */
226	        priv->hw->ctrl.cpol = 0;
227	        priv->hw->ctrl.cpha = 1;
228	        break;
229	
230	      case SPIDEV_MODE2: /* CPOL=1 CPHA=0 */
231	        priv->hw->ctrl.cpol = 1;
232	        priv->hw->ctrl.cpha = 0;
233	        break;
234	
235	      case SPIDEV_MODE3: /* CPOL=1 CPHA=1 */
236	        priv->hw->ctrl.cpol = 1;
237	        priv->hw->ctrl.cpha = 1;
238	        break;
239	
240	      default:
241	        printf("SPI1: ERROR invalid mode %d\n", mode);
242	        return;
243	    }
244	
245	  priv->mode = mode;
246	}
