72	    struct lcd_planeinfo_s pinfo;
73	    lv_display_t * disp;
74	    int fd;
75	    int ret;
76	
77	    LV_ASSERT_NULL(dev_path);
78	
79	    LV_LOG_USER("lcd %s opening", dev_path);
80	    fd = open(dev_path, O_CLOEXEC);
81	    if(fd < 0) {
82	        perror("Error: cannot open lcd device");
83	        return NULL;
84	    }
85	
86	    LV_LOG_USER("lcd %s open success", dev_path);
87	
88	    ret = ioctl(fd, LCDDEVIO_GETVIDEOINFO,
89	                (unsigned long)((uintptr_t)&vinfo));
90	    if(ret < 0) {
91	        perror("Error: ioctl(LCDDEVIO_GETVIDEOINFO) failed");
92	        close(fd);
93	        return NULL;
94	    }
95	
96	    ret = ioctl(fd, LCDDEVIO_GETPLANEINFO,
97	                (unsigned long)((uintptr_t)&pinfo));
98	    if(ret < 0) {
99	        perror("ERROR: ioctl(LCDDEVIO_GETPLANEINFO) failed");
100	        close(fd);
101	        return NULL;
102	    }
103	
104	    disp = lcd_init(fd, vinfo.xres, vinfo.yres);
105	    if(disp == NULL) {
106	        close(fd);
107	    }
108	
109	    return disp;
110	}
