115	
116	static int32_t align_round_up(int32_t v, uint16_t align)
117	{
118	    return (v + align - 1) & ~(align - 1);
119	}
120	
121	static void rounder_cb(lv_event_t * e)
122	{
123	    lv_nuttx_lcd_t * lcd = lv_event_get_user_data(e);
124	    lv_area_t * area = lv_event_get_param(e);
125	    struct lcddev_area_align_s * align_info = &lcd->align_info;
126	    int32_t w;
127	    int32_t h;
128	
129	    area->x1 &= ~(align_info->col_start_align - 1);
130	    area->y1 &= ~(align_info->row_start_align - 1);
131	
132	    w = align_round_up(lv_area_get_width(area), align_info->width_align);
133	    h = align_round_up(lv_area_get_height(area), align_info->height_align);
134	
135	    area->x2 = area->x1 + w - 1;
136	    area->y2 = area->y1 + h - 1;
137	}
138	
139	/* M4 frame-rate probe: measure the LCDDEVIO_PUTAREA ioctl duration (SPI
140	 * throughput) and periodic flush rate.  Guarded by the first-40 + every-100
141	 * log pattern so steady-state stays quiet.  Remove after M4 settles. */
142	static int s_flush_count = 0;
143	static struct timespec s_rate_t0;
144	
145	static void flush_cb(lv_display_t * disp, const lv_area_t * area_p,
146	                     uint8_t * color_p)
147	{
148	    lv_nuttx_lcd_t * lcd = disp->driver_data;
149	    int ret;
150	    struct timespec t0, t1;
151	    long us;
152	
153	    lcd->area.row_start = area_p->y1;
154	    lcd->area.row_end = area_p->y2;
155	    lcd->area.col_start = area_p->x1;
156	    lcd->area.col_end = area_p->x2;
157	    lcd->area.data = (uint8_t *)color_p;
158	
159	    clock_gettime(CLOCK_MONOTONIC, &t0);
160	    ret = ioctl(lcd->fd, LCDDEVIO_PUTAREA, (unsigned long) & (lcd->area));
161	    clock_gettime(CLOCK_MONOTONIC, &t1);
162	
163	    us = (t1.tv_sec - t0.tv_sec) * 1000000 + (t1.tv_nsec - t0.tv_nsec) / 1000;
164	
165	    if (s_flush_count == 0)
166	      s_rate_t0 = t0;
167	
168	    if (s_flush_count < 40 || ret < 0)
169	      {
170	        int w = area_p->x2 - area_p->x1 + 1;
171	        int h = area_p->y2 - area_p->y1 + 1;
172	        /* (w*h*2) bytes / us = bytes per microsecond = MB/s (decimal). */
173	        syslog(LOG_INFO, "[lv_nuttx_lcd] flush #%d %dx%d rc=%d %ldus"
174	               " (%ld MB/s)\n", ++s_flush_count, w, h, ret, us,
175	               us > 0 ? (long)((w * h * 2) / us) : 0);
176	      }
177	    else
178	      {
179	        s_flush_count++;
180	      }
181	
182	    /* Every 100 flushes: report the rolling flush rate. */
183	    if (s_flush_count >= 100 && (s_flush_count % 100) == 0)
184	      {
185	        long ms = (t1.tv_sec - s_rate_t0.tv_sec) * 1000
186	                + (t1.tv_nsec - s_rate_t0.tv_nsec) / 1000000;
187	        syslog(LOG_INFO, "[lv_nuttx_lcd] rate: %d flushes in %ldms"
188	               " (%.1f flush/s)\n", s_flush_count, ms,
189	               ms > 0 ? (float)s_flush_count * 1000.0f / ms : 0.0f);
190	        s_rate_t0 = t1;
191	      }
192	
193	    lv_display_flush_ready(disp);
194	}
195	
196	static lv_display_t * lcd_init(int fd, int hor_res, int ver_res)
197	{
198	    lv_color_t * draw_buf = NULL;
199	    lv_color_t * draw_buf_2 = NULL;
200	    lv_nuttx_lcd_t * lcd = lv_malloc_zeroed(sizeof(lv_nuttx_lcd_t));
201	    LV_ASSERT_MALLOC(lcd);
202	    if(lcd == NULL) {
203	        LV_LOG_ERROR("lv_nuttx_lcd_t malloc failed");
204	        return NULL;
205	    }
206	
207	    lv_display_t * disp = lv_display_create(hor_res, ver_res);
208	    if(disp == NULL) {
209	        lv_free(lcd);
210	        return NULL;
211	    }
212	
213	    uint32_t px_size = lv_color_format_get_size(lv_display_get_color_format(disp));
214	#if LV_NUTTX_LCD_BUFFER_COUNT > 0
215	    uint32_t buf_size = hor_res * ver_res * px_size;
216	    lv_display_render_mode_t render_mode = LV_DISPLAY_RENDER_MODE_FULL;
217	#else
218	    uint32_t buf_size = hor_res * LV_NUTTX_LCD_BUFFER_SIZE * px_size;
219	    lv_display_render_mode_t render_mode = LV_DISPLAY_RENDER_MODE_PARTIAL;
220	#endif
221	
222	    draw_buf = lv_malloc(buf_size);
223	    if(draw_buf == NULL) {
224	        LV_LOG_ERROR("display draw_buf malloc failed");
225	        lv_free(lcd);
226	        return NULL;
227	    }
228	
229	#if LV_NUTTX_LCD_BUFFER_COUNT == 2
230	    draw_buf_2 = lv_malloc(buf_size);
231	    if(draw_buf_2 == NULL) {
232	        LV_LOG_ERROR("display draw_buf_2 malloc failed");
233	        lv_free(lcd);
234	        lv_free(draw_buf);
235	        return NULL;
236	    }
237	#endif
238	
239	    lcd->fd = fd;
240	    if(ioctl(fd, LCDDEVIO_GETAREAALIGN, &lcd->align_info) < 0) {
241	        perror("Error: ioctl(LCDDEVIO_GETAREAALIGN) failed");
242	    }
243	
244	    lcd->disp = disp;
245	    lv_display_set_buffers(lcd->disp, draw_buf, draw_buf_2, buf_size, render_mode);
246	    lv_display_set_flush_cb(lcd->disp, flush_cb);
247	    lv_display_add_event_cb(lcd->disp, rounder_cb, LV_EVENT_INVALIDATE_AREA, lcd);
248	    lv_display_add_event_cb(lcd->disp, display_release_cb, LV_EVENT_DELETE, lcd->disp);
249	    lv_display_set_driver_data(lcd->disp, lcd);
250	
251	    return lcd->disp;
252	}
253	
254	static void display_release_cb(lv_event_t * e)
255	{
256	    lv_display_t * disp = (lv_display_t *) lv_event_get_user_data(e);
257	    lv_nuttx_lcd_t * dsc = lv_display_get_driver_data(disp);
258	    if(dsc) {
259	        lv_display_set_driver_data(disp, NULL);
260	        lv_display_set_flush_cb(disp, NULL);
261	
262	        /* clear display buffer */
263	        if(disp->buf_1) {
264	            lv_free(disp->buf_1);
265	            disp->buf_1 = NULL;
266	        }
267	        if(disp->buf_2) {
268	            lv_free(disp->buf_2);
269	            disp->buf_2 = NULL;
270	        }
271	
272	        /* close device fb */
273	        if(dsc->fd >= 0) {
274	            close(dsc->fd);
275	            dsc->fd = -1;
276	        }
277	        lv_free(dsc);
278	        LV_LOG_USER("Done");
279	    }
280	}
