193	static void stop_anim(void)
194	{
195	  /* Delete any anim bound to our widgets. lv_anim_delete is a no-op if none. */
196	  if (s_pet.ring)   lv_anim_delete(s_pet.ring,   spin_cb);
197	  if (s_pet.sprite) lv_anim_delete(s_pet.sprite, breathe_cb);
198	  if (s_pet.sprite) lv_anim_delete(s_pet.sprite, shake_cb);
199	  if (s_pet.sprite) lv_anim_delete(s_pet.sprite, blink_cb);
200	  if (s_pet.sprite) lv_anim_delete(s_pet.sprite, float_cb);
201	  s_pet.anim_active = false;
202	}
203	
204	/* Per-state face: each agent state shows a distinct expression (eyes-only edits
205	 * on the CC0 base face — see gen_pet_expressions.py).  WAITING returns the
206	 * open-eye base because its blink anim swaps base↔blink itself. */
207	static const lv_image_dsc_t *sprite_for(enum pet_state st)
208	{
209	  switch (st)
210	    {
211	      case PET_STATE_LISTENING: return s_frames->eyes_down;
212	      case PET_STATE_THINKING:  return s_frames->eyes_up;
213	      case PET_STATE_EXECUTING: return s_frames->focused;
214	      case PET_STATE_ERROR:     return s_frames->error;
215	      case PET_STATE_WAITING:
216	      case PET_STATE_IDLE:
217	      default:                  return s_frames->base;
218	    }
219	}
220	
221	static void start_anim_for(enum pet_state st)
222	{
223	  lv_anim_t a;
224	  uint32_t color = s_state_color[st];
225	
226	  stop_anim();
227	  if (!s_pet.ring || !s_pet.sprite) return;
228	
229	  /* Indicator color always tracks state (the dark track stays constant);
230	   * base angles reset per effect. */
231	  lv_obj_set_style_arc_color(s_pet.ring, lv_color_hex(color), LV_PART_INDICATOR);
232	
233	  /* Face tracks state too — each state's expression frame (blink anim swaps it). */
234	  lv_image_set_src(s_pet.sprite, sprite_for(st));
235	
236	  switch (st)
237	    {
238	      case PET_STATE_THINKING:
239	      case PET_STATE_LISTENING:
240	        lv_anim_init(&a);
241	        lv_anim_set_var(&a, s_pet.ring);
242	        lv_anim_set_values(&a, 0, 360);
243	        lv_anim_set_time(&a, 1400);
244	        lv_anim_set_exec_cb(&a, spin_cb);
245	        lv_anim_set_repeat_count(&a, LV_ANIM_REPEAT_INFINITE);
246	        lv_anim_start(&a);
247	        break;
248	      case PET_STATE_EXECUTING:
249	        lv_anim_init(&a);
250	        lv_anim_set_var(&a, s_pet.ring);
251	        lv_anim_set_values(&a, 0, 360);
252	        lv_anim_set_time(&a, 900);
253	        lv_anim_set_exec_cb(&a, fill_cb);
254	        lv_anim_set_repeat_count(&a, LV_ANIM_REPEAT_INFINITE);
255	        lv_anim_start(&a);
256	        break;
257	      case PET_STATE_IDLE:
258	        lv_anim_init(&a);
259	        lv_anim_set_var(&a, s_pet.sprite);
260	        lv_anim_set_values(&a, 0, 100);
261	        lv_anim_set_time(&a, 1800);
262	        lv_anim_set_exec_cb(&a, breathe_cb);
263	        lv_anim_set_repeat_count(&a, LV_ANIM_REPEAT_INFINITE);
264	        lv_anim_start(&a);
265	        /* Layered float: a slow bob on a distinct period so the two effects
266	         * don't phase-lock.  lv_anim_start copies `a`, so it is safe to reuse
267	         * the same local descriptor for a second anim. */
268	        lv_anim_init(&a);
269	        lv_anim_set_var(&a, s_pet.sprite);
270	        lv_anim_set_values(&a, 0, 100);
271	        lv_anim_set_time(&a, 2600);
272	        lv_anim_set_exec_cb(&a, float_cb);
273	        lv_anim_set_repeat_count(&a, LV_ANIM_REPEAT_INFINITE);
274	        lv_anim_start(&a);
275	        lv_arc_set_angles(s_pet.ring, 0, 360);  /* full ring */
276	        break;
277	      case PET_STATE_WAITING:
278	        lv_anim_init(&a);
279	        lv_anim_set_var(&a, s_pet.sprite);
280	        lv_anim_set_values(&a, 0, 100);
281	        lv_anim_set_time(&a, 900);
282	        lv_anim_set_exec_cb(&a, blink_cb);
283	        lv_anim_set_repeat_count(&a, LV_ANIM_REPEAT_INFINITE);
284	        lv_anim_start(&a);
285	        lv_arc_set_angles(s_pet.ring, 0, 360);
286	        break;
287	      case PET_STATE_ERROR:
288	        lv_anim_init(&a);
289	        lv_anim_set_var(&a, s_pet.sprite);
290	        lv_anim_set_values(&a, 0, 100);
291	        lv_anim_set_time(&a, 350);
292	        lv_anim_set_exec_cb(&a, shake_cb);
293	        lv_anim_set_repeat_count(&a, LV_ANIM_REPEAT_INFINITE);
294	        lv_anim_start(&a);
295	        lv_arc_set_angles(s_pet.ring, 0, 360);
296	        break;
297	      default:
298	        lv_arc_set_angles(s_pet.ring, 0, 360);
299	        break;
300	    }
301	  s_pet.anim_active = true;
302	}
303	
304	/* ---------- async apply (runs in LVGL thread) ---------- */
305	
306	static void apply_state_async_cb(void *data)
307	{
308	  enum pet_state st = (enum pet_state)(intptr_t)data;
309	  if (!s_pet.initialized || !s_pet.sprite) return;
310	
311	  s_pet.state = st;
312	
313	  /* Reset the sprite to a clean base frame; per-state anim re-derives it. */
314	  lv_image_set_src(s_pet.sprite, s_frames->base);
315	  lv_obj_set_style_translate_x(s_pet.sprite, 0, 0);  /* clear any shake offset */
316	  lv_obj_set_style_translate_y(s_pet.sprite, 0, 0);  /* clear any float offset */
317	  lv_obj_set_style_opa(s_pet.sprite, LV_OPA_COVER, 0);
318	
319	  if (s_pet.label) lv_label_set_text(s_pet.label, s_state_text[st]);
320	  if (s_pet.status_dot) {
321	    lv_obj_set_style_bg_color(s_pet.status_dot, lv_color_hex(s_state_color[st]), 0);
322	  }
323	
324	  start_anim_for(st);
325	  syslog(LOG_INFO, "[%s] state → %s\n", TAG, s_state_text[st]);
326	}
327	
328	void pet_status_view_set_state(enum pet_state state)
329	{
330	  if ((int)state < 0 || (int)state > PET_STATE_ERROR) return;
331	  /* Async: widget mutation must happen in the LVGL thread. */
332	  lv_async_call(apply_state_async_cb, (void *)(intptr_t)state);
333	}
334	
335	static void apply_type_async_cb(void *data)
336	{
337	  enum pet_type type = (enum pet_type)(intptr_t)data;
338	  if (!s_pet.initialized || !s_pet.sprite) return;
339	
340	  s_pet.type = type;
341	  s_frames = &s_frames_by_type[type];
342	
343	  /* Re-derive the current state's expression under the new sprite sheet and
344	   * restart its anim (blink_cb reads s_frames, so it picks up the swap too). */
345	  lv_image_set_src(s_pet.sprite, s_frames->base);
346	  lv_obj_set_style_translate_x(s_pet.sprite, 0, 0);
347	  lv_obj_set_style_translate_y(s_pet.sprite, 0, 0);
348	  lv_obj_set_style_opa(s_pet.sprite, LV_OPA_COVER, 0);
349	
350	  start_anim_for(s_pet.state);
351	  syslog(LOG_INFO, "[%s] type → %d\n", TAG, (int)type);
352	}
353	
354	void pet_status_view_set_type(int type)
355	{
356	  if (type < 0 || type >= PET_TYPE_COUNT) type = PET_TYPE_CAT;
357	  lv_async_call(apply_type_async_cb, (void *)(intptr_t)type);
358	}
359	
360	/* ---------- screen show / hide ---------- */
361	
362	static void show_async_cb(void *data)
363	{
364	  (void)data;
365	  if (!s_pet.initialized || !s_pet.screen || s_pet.visible) return;
366	  s_pet.prev_screen = lv_screen_active();
367	  lv_screen_load(s_pet.screen);
368	  /* lv_screen_load already invalidates the full screen and schedules a redraw;
369	   * the explicit invalidate + lv_refr_now below was a qemu-goldfish-headless
370	   * lazy-flush workaround that is unnecessary on the real CP /dev/lcd0 panel,
371	   * where it caused a full-frame (top-to-bottom) white flicker on every idle
372	   * pet↔particle rotate.  Real hardware renders screen switches fine without
373	   * the extra synchronous refresh, so we drop it to stop the standby flicker. */
374	  s_pet.visible = true;
375	  /* Re-assert current state's animation (lv_anim may have been paused off-screen). */
376	  start_anim_for(s_pet.state);
377	  syslog(LOG_INFO, "[%s] pet screen shown\n", TAG);
378	}
379	
380	void pet_status_view_show(void)
381	{
382	  if (!s_pet.initialized) return;
383	  lv_async_call(show_async_cb, NULL);
384	}
385	
386	static void hide_async_cb(void *data)
387	{
388	  (void)data;
389	  if (!s_pet.initialized || !s_pet.visible) return;
390	  stop_anim();
391	  if (s_pet.prev_screen) lv_screen_load(s_pet.prev_screen);
392	  s_pet.visible = false;
393	  syslog(LOG_INFO, "[%s] pet screen hidden\n", TAG);
394	}
395	
396	void pet_status_view_hide(void)
397	{
398	  if (!s_pet.initialized) return;
399	  lv_async_call(hide_async_cb, NULL);
400	}
401	
402	bool pet_status_view_is_visible(void)
403	{
404	  return s_pet.visible;
405	}
