407	/* ---------- init ---------- */
408	
409	int pet_status_view_init(void)
410	{
411	  if (s_pet.initialized) return 0;
412	
413	  memset(&s_pet, 0, sizeof(s_pet));
414	  s_pet.state = PET_STATE_IDLE;
415	  s_pet.type = PET_TYPE_CAT;
416	  s_frames = &s_frames_by_type[PET_TYPE_CAT];
417	
418	  s_pet.screen = lv_obj_create(NULL);
419	  if (!s_pet.screen) return -ENOMEM;
420	  lv_obj_set_style_bg_color(s_pet.screen, lv_color_hex(UI_PAL_BG), 0);
421	  lv_obj_set_style_bg_opa(s_pet.screen, LV_OPA_COVER, 0);
422	  lv_obj_set_style_text_font(s_pet.screen, &lv_font_misans_16_cjk, 0);
423	
424	  /* Ring (arc) — centered, subtle dark track, state-colored indicator. */
425	  s_pet.ring = lv_arc_create(s_pet.screen);
426	  if (s_pet.ring)
427	    {
428	      lv_obj_set_size(s_pet.ring, PET_RING_SIZE, PET_RING_SIZE);
429	      lv_obj_center(s_pet.ring);
430	      lv_arc_set_rotation(s_pet.ring, 0);
431	      lv_arc_set_bg_angles(s_pet.ring, 0, 360);
432	      lv_arc_set_angles(s_pet.ring, 0, 360);
433	      lv_arc_set_range(s_pet.ring, 0, 360);
434	      /* Track (LV_PART_MAIN): a subtle dark full circle that stays put. */
435	      lv_obj_set_style_arc_width(s_pet.ring, 4, LV_PART_MAIN);
436	      lv_obj_set_style_arc_color(s_pet.ring, lv_color_hex(UI_PAL_TRACK), LV_PART_MAIN);
437	      lv_obj_set_style_arc_rounded(s_pet.ring, true, LV_PART_MAIN);
438	      /* Indicator (LV_PART_INDICATOR): the state-colored spinner / fill.
439	       * (Previously only LV_PART_MAIN was styled, so the animated segment fell
440	       * back to the theme's default blue arc — the "ugly" ring.) */
441	      lv_obj_set_style_arc_width(s_pet.ring, 4, LV_PART_INDICATOR);
442	      lv_obj_set_style_arc_color(s_pet.ring, lv_color_hex(UI_PAL_IDLE), LV_PART_INDICATOR);
443	      lv_obj_set_style_arc_rounded(s_pet.ring, true, LV_PART_INDICATOR);
444	      lv_obj_remove_flag(s_pet.ring, LV_OBJ_FLAG_CLICKABLE);
445	      /* Hide the arc knob. */
446	      lv_obj_set_style_bg_opa(s_pet.ring, LV_OPA_TRANSP, LV_PART_KNOB);
447	    }
448	
449	  /* Pixel pet — CC0 sprite scaled 6x (nearest-neighbor for crisp pixels). */
450	  s_pet.sprite = lv_image_create(s_pet.screen);
451	  if (!s_pet.sprite) goto fail;
452	  lv_image_set_src(s_pet.sprite, s_frames->base);
453	  lv_image_set_antialias(s_pet.sprite, false);
454	  lv_image_set_scale(s_pet.sprite, PET_SPRITE_SCALE * 256);
455	  lv_obj_center(s_pet.sprite);
456	
457	  /* Status caption row below the sprite: a colored status dot (HachimoDock
458	   * circular status marker) + the state text, laid out horizontally. */
459	  {
460	    lv_obj_t *caption = lv_obj_create(s_pet.screen);
461	    if (!caption) goto fail;
462	    lv_obj_remove_flag(caption, LV_OBJ_FLAG_SCROLLABLE);
463	    lv_obj_set_size(caption, LV_SIZE_CONTENT, LV_SIZE_CONTENT);
464	    lv_obj_set_style_bg_opa(caption, LV_OPA_TRANSP, 0);
465	    lv_obj_set_style_border_width(caption, 0, 0);
466	    lv_obj_set_style_pad_all(caption, 0, 0);
467	    lv_obj_set_flex_flow(caption, LV_FLEX_FLOW_ROW);
468	    lv_obj_set_flex_align(caption, LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER,
469	                          LV_FLEX_ALIGN_CENTER);
470	    lv_obj_set_style_pad_column(caption, 6, 0);
471	    lv_obj_align(caption, LV_ALIGN_CENTER, 0, PET_LABEL_DY);
472	
473	    s_pet.status_dot = lv_obj_create(caption);
474	    if (s_pet.status_dot)
475	      {
476	        lv_obj_remove_flag(s_pet.status_dot, LV_OBJ_FLAG_SCROLLABLE);
477	        lv_obj_set_size(s_pet.status_dot, 8, 8);
478	        lv_obj_set_style_radius(s_pet.status_dot, LV_RADIUS_CIRCLE, 0);
479	        lv_obj_set_style_bg_color(s_pet.status_dot, lv_color_hex(UI_PAL_IDLE), 0);
480	        lv_obj_set_style_bg_opa(s_pet.status_dot, LV_OPA_COVER, 0);
481	        lv_obj_set_style_border_width(s_pet.status_dot, 0, 0);
482	        lv_obj_set_style_pad_all(s_pet.status_dot, 0, 0);
483	      }
484	
485	    s_pet.label = lv_label_create(caption);
486	    if (s_pet.label)
487	      {
488	        lv_label_set_text(s_pet.label, s_state_text[PET_STATE_IDLE]);
489	        lv_obj_set_style_text_color(s_pet.label, lv_color_hex(UI_PAL_TEXT_DIM), 0);
490	        lv_obj_set_style_text_font(s_pet.label, &lv_font_misans_16_cjk, 0);
491	      }
492	  }
493	
494	  s_pet.initialized = true;
495	  syslog(LOG_INFO, "[%s] init OK (像素宠物状态环)\n", TAG);
496	  return 0;
497	
498	fail:
499	  if (s_pet.screen) lv_obj_del(s_pet.screen);
500	  memset(&s_pet, 0, sizeof(s_pet));
501	  return -ENOMEM;
502	}
