77	struct pet_state_s {
78	  bool initialized;
79	  bool visible;
80	  enum pet_state state;
81	  enum pet_type type;
82	  lv_obj_t *screen;
83	  lv_obj_t *ring;     /* lv_arc: status ring around sprite */
84	  lv_obj_t *sprite;   /* lv_image: pixel-art pet (scaled) */
85	  lv_obj_t *label;
86	  lv_obj_t *status_dot; /* colored dot next to the state caption */
87	  lv_obj_t *prev_screen;
88	  /* active animation tag — one effect at a time, stopped on state change */
89	  bool anim_active;
90	};
91	
92	static struct pet_state_s s_pet;
93	
94	/* Per-type expression frame tables.  All six faces share the same state→face
95	 * mapping (base/blink/eyes_up/eyes_down/focused/error); the pet type only
96	 * swaps which sprite sheet supplies those faces. */
97	struct pet_frames_s {
98	  const lv_image_dsc_t *base;      /* IDLE / WAITING open-eye frame */
99	  const lv_image_dsc_t *blink;     /* WAITING closed-eye frame */
100	  const lv_image_dsc_t *eyes_up;   /* THINKING */
101	  const lv_image_dsc_t *eyes_down; /* LISTENING */
102	  const lv_image_dsc_t *focused;   /* EXECUTING */
103	  const lv_image_dsc_t *error;     /* ERROR */
104	};
105	
106	static const struct pet_frames_s s_frames_by_type[PET_TYPE_COUNT] = {
107	  [PET_TYPE_CAT]  = {
108	    &pet_sprite_base, &pet_sprite_blink, &pet_sprite_eyes_up,
109	    &pet_sprite_eyes_down, &pet_sprite_focused, &pet_sprite_error,
110	  },
111	  [PET_TYPE_FROG] = {
112	    &frog_sprite_base, &frog_sprite_blink, &frog_sprite_eyes_up,
113	    &frog_sprite_eyes_down, &frog_sprite_focused, &frog_sprite_error,
114	  },
115	  [PET_TYPE_BLACKCAT] = {
116	    &blackcat_sprite_base, &blackcat_sprite_blink, &blackcat_sprite_eyes_up,
117	    &blackcat_sprite_eyes_down, &blackcat_sprite_focused, &blackcat_sprite_error,
118	  },
119	  [PET_TYPE_DOG] = {
120	    &dog_sprite_base, &dog_sprite_blink, &dog_sprite_eyes_up,
121	    &dog_sprite_eyes_down, &dog_sprite_focused, &dog_sprite_error,
122	  },
123	  [PET_TYPE_PIG] = {
124	    &pig_sprite_base, &pig_sprite_blink, &pig_sprite_eyes_up,
125	    &pig_sprite_eyes_down, &pig_sprite_focused, &pig_sprite_error,
126	  },
127	};
128	
129	static const struct pet_frames_s *s_frames = &s_frames_by_type[PET_TYPE_CAT];
130	
131	/* ---------- animation exec callbacks (LVGL v9: (obj, value)) ---------- */
132	
133	/* LVGL v9 exec_cb signature is lv_anim_exec_xcb_t = void(*)(void*, lv_anim_value_t),
134	 * i.e. the first arg is the animated var (void*), NOT lv_obj_t* nor lv_anim_t*.
135	 * We cast to lv_obj_t* inside for the lv_obj and lv_arc calls. */
136	/* Spinner: a 90° segment rotating (THINKING / LISTENING). value = start angle. */
137	static void spin_cb(void *obj, int32_t v)
138	{
139	  lv_obj_t *o = (lv_obj_t *)obj;
140	  lv_arc_set_angles(o, v, v + 90);
141	}
142	
143	/* Growing fill: indicator grows 0→360 (EXECUTING). value = end angle. */
144	static void fill_cb(void *obj, int32_t v)
145	{
146	  lv_obj_t *o = (lv_obj_t *)obj;
147	  lv_arc_set_angles(o, 0, v);
148	}
149	
150	/* Breathing: sprite opacity pulses (IDLE). value 0..100. */
151	static void breathe_cb(void *obj, int32_t v)
152	{
153	  lv_obj_t *o = (lv_obj_t *)obj;
154	  /* 100% → 255, 0% → 190 (gentle). */
155	  lv_obj_set_style_opa(o, LV_OPA_COVER - (v * (LV_OPA_COVER - 190)) / 100, 0);
156	}
157	
158	/* Float: gentle vertical bob (IDLE, layered with the opacity breathe so the
159	 * idle pet feels alive rather than a static icon). value 0..100. */
160	static void float_cb(void *obj, int32_t v)
161	{
162	  lv_obj_t *o = (lv_obj_t *)obj;
163	  /* Triangle 0→+2→0→-2→0 across one cycle — a ±2px bob on a 96px sprite. */
164	  int32_t amp;
165	  if (v < 25)      amp = (v * 2) / 25;
166	  else if (v < 50) amp = ((50 - v) * 2) / 25;
167	  else if (v < 75) amp = -((v - 50) * 2) / 25;
168	  else             amp = -((100 - v) * 2) / 25;
169	  lv_obj_set_style_translate_y(o, amp, 0);
170	}
171	
172	/* Blink: swap between open/closed eyes (WAITING). value 0..100, closed at mid. */
173	static void blink_cb(void *obj, int32_t v)
174	{
175	  lv_obj_t *o = (lv_obj_t *)obj;
176	  /* open → closed(35..65) → open.  Two-frame swap reads as a pixel blink. */
177	  lv_image_set_src(o, (v >= 35 && v <= 65) ? s_frames->blink
178	                                            : s_frames->base);
179	}
180	
181	/* Shake: sprite x jitter (ERROR). value 0..100 maps to a few oscillations. */
182	static void shake_cb(void *obj, int32_t v)
183	{
184	  lv_obj_t *o = (lv_obj_t *)obj;
185	  /* 0..100 → four half-swings of ±5px. Simple triangle per 25-step. */
186	  int seg = v / 25;
187	  int phase = v % 25;
188	  int amp = (phase < 13) ? (phase * 5 / 12) : ((25 - phase) * 5 / 12);
189	  int sign = (seg % 2 == 0) ? 1 : -1;
190	  lv_obj_set_style_translate_x(o, sign * amp, 0);
191	}
192	
193	static void stop_anim(void)
194	{
195	  /* Delete any anim bound to our widgets. lv_anim_delete is a no-op if none. */
196	  if (s_pet.ring)   lv_anim_delete(s_pet.ring,   spin_cb);
197	  if (s_pet.sprite) lv_anim_delete(s_pet.sprite, breathe_cb);
198	  if (s_pet.sprite) lv_anim_delete(s_pet.sprite, shake_cb);
199	  if (s_pet.sprite) lv_anim_delete(s_pet.sprite, blink_cb);
200	  if (s_pet.sprite) lv_anim_delete(s_pet.sprite, float_cb);
201	  s_pet.anim_active = false;
202	}
203	
204	/* Per-state face: each agent state shows a distinct expression (eyes-only edits
205	 * on the CC0 base face — see gen_pet_expressions.py).  WAITING returns the
206	 * open-eye base because its blink anim swaps base↔blink itself. */
207	static const lv_image_dsc_t *sprite_for(enum pet_state st)
208	{
209	  switch (st)
210	    {
211	      case PET_STATE_LISTENING: return s_frames->eyes_down;
212	      case PET_STATE_THINKING:  return s_frames->eyes_up;
213	      case PET_STATE_EXECUTING: return s_frames->focused;
214	      case PET_STATE_ERROR:     return s_frames->error;
215	      case PET_STATE_WAITING:
216	      case PET_STATE_IDLE:
217	      default:                  return s_frames->base;
218	    }
219	}
220	
221	static void start_anim_for(enum pet_state st)
222	{
223	  lv_anim_t a;
224	  uint32_t color = s_state_color[st];
225	
226	  stop_anim();
227	  if (!s_pet.ring || !s_pet.sprite) return;
228	
229	  /* Indicator color always tracks state (the dark track stays constant);
230	   * base angles reset per effect. */
231	  lv_obj_set_style_arc_color(s_pet.ring, lv_color_hex(color), LV_PART_INDICATOR);
232	
233	  /* Face tracks state too — each state's expression frame (blink anim swaps it). */
234	  lv_image_set_src(s_pet.sprite, sprite_for(st));
235	
236	  switch (st)
237	    {
238	      case PET_STATE_THINKING:
239	      case PET_STATE_LISTENING:
240	        lv_anim_init(&a);
241	        lv_anim_set_var(&a, s_pet.ring);
242	        lv_anim_set_values(&a, 0, 360);
243	        lv_anim_set_time(&a, 1400);
244	        lv_anim_set_exec_cb(&a, spin_cb);
245	        lv_anim_set_repeat_count(&a, LV_ANIM_REPEAT_INFINITE);
246	        lv_anim_start(&a);
247	        break;
248	      case PET_STATE_EXECUTING:
249	        lv_anim_init(&a);
250	        lv_anim_set_var(&a, s_pet.ring);
251	        lv_anim_set_values(&a, 0, 360);
252	        lv_anim_set_time(&a, 900);
253	        lv_anim_set_exec_cb(&a, fill_cb);
254	        lv_anim_set_repeat_count(&a, LV_ANIM_REPEAT_INFINITE);
255	        lv_anim_start(&a);
256	        break;
257	      case PET_STATE_IDLE:
258	        lv_anim_init(&a);
259	        lv_anim_set_var(&a, s_pet.sprite);
260	        lv_anim_set_values(&a, 0, 100);
261	        lv_anim_set_time(&a, 1800);
262	        lv_anim_set_exec_cb(&a, breathe_cb);
263	        lv_anim_set_repeat_count(&a, LV_ANIM_REPEAT_INFINITE);
264	        lv_anim_start(&a);
265	        /* Layered float: a slow bob on a distinct period so the two effects
266	         * don't phase-lock.  lv_anim_start copies `a`, so it is safe to reuse
267	         * the same local descriptor for a second anim. */
268	        lv_anim_init(&a);
269	        lv_anim_set_var(&a, s_pet.sprite);
270	        lv_anim_set_values(&a, 0, 100);
271	        lv_anim_set_time(&a, 2600);
272	        lv_anim_set_exec_cb(&a, float_cb);
273	        lv_anim_set_repeat_count(&a, LV_ANIM_REPEAT_INFINITE);
274	        lv_anim_start(&a);
275	        lv_arc_set_angles(s_pet.ring, 0, 360);  /* full ring */
276	        break;
277	      case PET_STATE_WAITING:
278	        lv_anim_init(&a);
279	        lv_anim_set_var(&a, s_pet.sprite);
280	        lv_anim_set_values(&a, 0, 100);
281	        lv_anim_set_time(&a, 900);
282	        lv_anim_set_exec_cb(&a, blink_cb);
283	        lv_anim_set_repeat_count(&a, LV_ANIM_REPEAT_INFINITE);
284	        lv_anim_start(&a);
285	        lv_arc_set_angles(s_pet.ring, 0, 360);
286	        break;
287	      case PET_STATE_ERROR:
288	        lv_anim_init(&a);
289	        lv_anim_set_var(&a, s_pet.sprite);
290	        lv_anim_set_values(&a, 0, 100);
291	        lv_anim_set_time(&a, 350);
292	        lv_anim_set_exec_cb(&a, shake_cb);
293	        lv_anim_set_repeat_count(&a, LV_ANIM_REPEAT_INFINITE);
294	        lv_anim_start(&a);
295	        lv_arc_set_angles(s_pet.ring, 0, 360);
296	        break;
297	      default:
298	        lv_arc_set_angles(s_pet.ring, 0, 360);
299	        break;
300	    }
301	  s_pet.anim_active = true;
302	}
