606	/* Semaphore for synchronizing async stop with LVGL thread */
607	static sem_t s_stop_sem;
608	
609	/* Internal cleanup — must be called from LVGL thread context */
610	static void lvgl_ui_do_cleanup(void)
611	{
612	    int i;
613	
614	    if (s_state.screen) {
615	        /* If our screen is the active screen, restore the previous
616	         * (launcher) screen first.  Deleting the active screen without
617	         * loading another one leaves LVGL with no valid screen — the
618	         * next lv_timer_handler() call crashes with a MemManage fault
619	         * (NULL pointer dereference at offset 0x32 in lv_obj_t). */
620	        if (s_state.screen_visible && s_state.prev_screen) {
621	            lv_screen_load(s_state.prev_screen);
622	        }
623	
624	        lv_obj_del(s_state.screen);
625	        s_state.screen = NULL;
626	    }
627	
628	    s_state.screen_visible = false;
629	    s_state.prev_screen = NULL;
630	
631	    s_state.chat_list = NULL;
632	
633	    for (i = 0; i < CHAT_HISTORY_MAX; i++) {
634	        s_state.history.msgs[i].bubble = NULL;
635	    }
636	
637	    s_state.history.head = 0;
638	    s_state.history.count = 0;
639	
640	    /* Note: when we self-initialized LVGL (s_lv_owned, qemu case), the
641	     * lv_timer_handler loop thread is intentionally left running — it is
642	     * torn down only when the ai_agent process exits.  Stopping it from
643	     * within cleanup (which itself runs in that loop thread via
644	     * lv_async_call) would self-deadlock.  Widget deletion above is safe
645	     * because the loop is still alive to process it. */
646	}
647	
648	static void stop_screen_async_cb(void* data)
649	{
650	    (void)data;
651	
652	    lvgl_ui_do_cleanup();
653	    sem_post(&s_stop_sem);
654	}
655	
656	/* Stop from an external thread (e.g. velaquit shutdown).
657	 * Schedules cleanup in the LVGL thread to avoid racing with the
658	 * miwear/launcher event loop. */
659	void lvgl_ui_channel_stop(void)
660	{
661	    /* No-op if not initialized or not running */
662	    if (!s_state.initialized || !s_state.running) {
663	        return;
664	    }
665	
666	    syslog(LOG_INFO, "[%s] stopping\n", TAG);
667	
668	    /* Mark as not running first — prevents callbacks (PTT,
669	     * chat_view_add_message) from touching widgets during teardown. */
670	    s_state.running = false;
671	
672	    /* Schedule cleanup in the LVGL thread to avoid racing with the
673	     * miwear/launcher event loop.  Direct lv_obj_del from the
674	     * shutdown thread causes a MemManage fault because the LVGL
675	     * thread may be mid-render on the same objects. */
676	    sem_init(&s_stop_sem, 0, 0);
677	    lv_async_call(stop_screen_async_cb, NULL);
678	
679	    /* Wait for LVGL thread to complete the deletion (timeout 2s) */
680	    struct timespec ts;
681	
682	    clock_gettime(CLOCK_REALTIME, &ts);
683	    ts.tv_sec += 2;
684	
685	    if (sem_timedwait(&s_stop_sem, &ts) != 0) {
686	        syslog(LOG_WARNING,
687	            "[%s] async stop timed out, forcing cleanup\n", TAG);
688	        /* Fallback: NULL out pointers without deleting (leak is
689	         * acceptable during shutdown to avoid crash). */
690	        s_state.screen = NULL;
691	        s_state.chat_list = NULL;
692	    }
693	
694	    sem_destroy(&s_stop_sem);
695	
696	    /* Destroy the mutex */
697	    pthread_mutex_destroy(&s_state.lock);
698	
699	    s_state.initialized = false;
700	
701	    syslog(LOG_INFO, "[%s] stopped\n", TAG);
702	}
