704	/* Async callback: load screen inside LVGL thread context */
705	static void show_screen_async_cb(void* data)
706	{
707	    (void)data;
708	    if (!s_state.initialized || !s_state.running || !s_state.screen) {
709	        return;
710	    }
711	    if (s_state.screen_visible) {
712	        return;
713	    }
714	
715	    /* CJK font selection happens at init() time via the statically-compiled
716	     * lv_font_misans_16_cjk (preferred: 3755 GB2312-1 common chars, baked into
717	     * the binary by lv_font_conv — zero runtime malloc, zero rasterization,
718	     * cannot corrupt the heap).  No runtime TTF loading here.
719	     *
720	     * History: we previously used lv_tiny_ttf_create_data() with a runtime
721	     * MiSans TTF, but stb_truetype's MakeGlyphBitmap write path overran its
722	     * output buffer on certain CJK glyphs and corrupted adjacent NuttX mm heap
723	     * chunk metadata, leading to recursive-assert reboots (mm_foreach /
724	     * nxsched_add_readytorun / nxsem_post_slow in the timer IRQ).  Subsetting
725	     * to 857 KB only delayed the crash; the root cause is the rasterizer, so
726	     * we moved to a pre-rasterized static font.  See lv_font_misans_16_cjk.c
727	     * and the fontgen notes in docs. */
728	    /* Already set in init(); nothing to do at show time. */
729	    syslog(LOG_INFO, "[%s] using static MiSans-16 CJK font\n", TAG);
730	
731	    syslog(LOG_INFO, "[%s] loading chat screen\n", TAG);
732	
733	    /* Save the current screen so we can restore it on stop.
734	     * The launcher (miwear) owns this screen — we must not delete it. */
735	    s_state.prev_screen = lv_screen_active();
736	
737	    lv_screen_load(s_state.screen);
738	    s_state.screen_visible = true;
739	
740	#ifdef LVGL_UI_CARD_SELFTEST
741	    /* Debug self-test: inject one card per reply category so all four
