290	/* Idle-yield support: when the pet status ring is enabled, the chat screen
291	 * yields the foreground to the pet after PET_IDLE_YIELD_MS of message silence.
292	 * All access is confined to the LVGL thread (init creates the timer; the send
293	 * async cb resets the tick; the timer cb does the yield). */
294	static lv_timer_t *s_pet_idle_timer = NULL;
295	static uint32_t    s_pet_last_msg_tick = 0;
296	
297	static void pet_idle_timer_cb(lv_timer_t *t)
298	{
299	    (void)t;
300	    if (!s_state.initialized || !s_state.screen_visible) return;
301	    /* A pending remote permission request owns the foreground: never yield it
302	     * back to the pet home screen while the approval page is up, or the user
303	     * loses the S2/S3 approve/cancel cue mid-decision. */
304	    if (s_state.approval_visible) return;
305	    if (!pet_status_view_is_visible() &&
306	        (lv_tick_get() - s_pet_last_msg_tick) >= PET_IDLE_YIELD_MS)
307	      {
308	        /* Yield: the chat screen stays alive but releases the foreground so
309	         * the pet home screen shows.  Clearing screen_visible lets the next
310	         * incoming message re-take the foreground via lvgl_ui_channel_show. */
311	        s_state.screen_visible = false;
312	        pet_status_view_show();
313	        syslog(LOG_INFO, "[%s] idle → pet home screen\n", TAG);
314	      }
315	}
