594	void lv_screen_load_anim(lv_obj_t * new_scr, lv_screen_load_anim_t anim_type, uint32_t time, uint32_t delay,
595	                         bool auto_del)
596	{
597	    lv_display_t * d = lv_obj_get_display(new_scr);
598	    lv_obj_t * act_scr = lv_screen_active();
599	
600	    if(act_scr == new_scr || d->scr_to_load == new_scr) {
601	        return;
602	    }
603	
604	    /*If another screen load animation is in progress
605	     *make target screen loaded immediately. */
606	    if(d->scr_to_load && act_scr != d->scr_to_load) {
607	        lv_anim_delete(d->scr_to_load, NULL);
608	        lv_obj_set_pos(d->scr_to_load, 0, 0);
609	        lv_obj_remove_local_style_prop(d->scr_to_load, LV_STYLE_OPA, 0);
610	
611	        if(d->del_prev) {
612	            lv_obj_delete(act_scr);
613	        }
614	        act_scr = lv_screen_active(); /*Active screen changed.*/
615	
616	        scr_load_internal(d->scr_to_load);
617	    }
618	
619	    d->scr_to_load = new_scr;
620	
621	    if(d->prev_scr && d->del_prev) {
622	        lv_obj_delete(d->prev_scr);
623	        d->prev_scr = NULL;
624	    }
625	
626	    d->draw_prev_over_act = is_out_anim(anim_type);
627	    d->del_prev = auto_del;
628	
629	    /*Be sure there is no other animation on the screens*/
630	    lv_anim_delete(new_scr, NULL);
631	    if(act_scr) lv_anim_delete(act_scr, NULL);
632	
633	    /*Be sure both screens are in a normal position*/
