793	static void refr_area(const lv_area_t * area_p)
794	{
795	    LV_PROFILER_REFR_BEGIN;
796	    lv_layer_t * layer = disp_refr->layer_head;
797	    layer->draw_buf = disp_refr->buf_act;
798	
799	    /*With full refresh just redraw directly into the buffer*/
800	    /*In direct mode draw directly on the absolute coordinates of the buffer*/
801	    if(disp_refr->render_mode != LV_DISPLAY_RENDER_MODE_PARTIAL) {
802	        layer->buf_area.x1 = 0;
803	        layer->buf_area.y1 = 0;
804	        if(lv_display_get_matrix_rotation(disp_refr)) {
805	            layer->buf_area.x2 = lv_display_get_original_horizontal_resolution(disp_refr) - 1;
806	            layer->buf_area.y2 = lv_display_get_original_vertical_resolution(disp_refr) - 1;
807	        }
808	        else {
809	            layer->buf_area.x2 = lv_display_get_horizontal_resolution(disp_refr) - 1;
810	            layer->buf_area.y2 = lv_display_get_vertical_resolution(disp_refr) - 1;
811	        }
812	        layer_reshape_draw_buf(layer, disp_refr->stride_is_auto ? LV_STRIDE_AUTO : layer->draw_buf->header.stride);
813	
814	        if(disp_refr->render_mode == LV_DISPLAY_RENDER_MODE_FULL) {
815	            lv_area_t disp_area;
816	            lv_area_set(&disp_area, 0, 0, lv_display_get_original_horizontal_resolution(disp_refr) - 1,
817	                        lv_display_get_original_vertical_resolution(disp_refr) - 1);
818	            disp_refr->last_part = 1;
819	            layer->_clip_area = disp_area;
820	            layer->phy_clip_area = disp_area;
821	            refr_area_part(layer);
822	        }
823	        else if(disp_refr->render_mode == LV_DISPLAY_RENDER_MODE_DIRECT) {
824	            disp_refr->last_part = disp_refr->last_area;
825	            layer->_clip_area = *area_p;
826	            layer->phy_clip_area = *area_p;
827	            refr_area_part(layer);
828	        }
829	        LV_PROFILER_REFR_END;
830	        return;
831	    }
832	
833	    /*Normal refresh: draw the area in parts*/
834	    /*Calculate the max row num*/
835	    int32_t w = lv_area_get_width(area_p);
836	    int32_t h = lv_area_get_height(area_p);
837	    int32_t y2 = area_p->y2 >= lv_display_get_vertical_resolution(disp_refr) ?
838	                 lv_display_get_vertical_resolution(disp_refr) - 1 : area_p->y2;
839	
840	    int32_t max_row = get_max_row(disp_refr, w, h);
841	
842	    int32_t row;
843	    int32_t row_last = 0;
844	    lv_area_t sub_area;
845	    for(row = area_p->y1; row + max_row - 1 <= y2; row += max_row) {
846	        /*Calc. the next y coordinates of draw_buf*/
847	        sub_area.x1 = area_p->x1;
848	        sub_area.x2 = area_p->x2;
849	        sub_area.y1 = row;
850	        sub_area.y2 = row + max_row - 1;
851	        layer->draw_buf = disp_refr->buf_act;
852	        layer->buf_area = sub_area;
853	        layer->_clip_area = sub_area;
854	        layer->phy_clip_area = sub_area;
855	        layer_reshape_draw_buf(layer, LV_STRIDE_AUTO);
856	        if(sub_area.y2 > y2) sub_area.y2 = y2;
857	        row_last = sub_area.y2;
858	        if(y2 == row_last) disp_refr->last_part = 1;
859	        refr_area_part(layer);
860	    }
861	
862	    /*If the last y coordinates are not handled yet ...*/
863	    if(y2 != row_last) {
864	        /*Calc. the next y coordinates of draw_buf*/
865	        sub_area.x1 = area_p->x1;
866	        sub_area.x2 = area_p->x2;
867	        sub_area.y1 = row;
868	        sub_area.y2 = y2;
869	        layer->draw_buf = disp_refr->buf_act;
870	        layer->buf_area = sub_area;
871	        layer->_clip_area = sub_area;
872	        layer->phy_clip_area = sub_area;
873	        layer_reshape_draw_buf(layer, LV_STRIDE_AUTO);
874	        disp_refr->last_part = 1;
875	        refr_area_part(layer);
876	    }
877	    LV_PROFILER_REFR_END;
878	}
