880	static void refr_area_part(lv_layer_t * layer)
881	{
882	    LV_PROFILER_REFR_BEGIN;
883	    disp_refr->refreshed_area = layer->_clip_area;
884	
885	    lv_layer_reset(layer);
886	
887	#if LV_DRAW_TRANSFORM_USE_MATRIX
888	    if(lv_display_get_matrix_rotation(disp_refr)) {
889	        const lv_display_rotation_t rotation = lv_display_get_rotation(disp_refr);
890	        if(rotation != LV_DISPLAY_ROTATION_0) {
891	            lv_display_rotate_area(disp_refr, &layer->phy_clip_area);
892	
893	            /**
894	             * The screen rotation direction defined by LVGL is opposite to the drawing angle.
895	             * Use direct matrix assignment to reduce precision loss and improve efficiency.
896	             */
897	            switch(rotation) {
898	                case LV_DISPLAY_ROTATION_90:
899	                    /**
900	                     * lv_matrix_rotate(&layer->matrix, 270);
901	                     * lv_matrix_translate(&layer->matrix, -disp_refr->ver_res, 0);
902	                     */
903	                    layer->matrix.m[0][0] = 0;
904	                    layer->matrix.m[0][1] = 1;
905	                    layer->matrix.m[0][2] = 0;
906	                    layer->matrix.m[1][0] = -1;
907	                    layer->matrix.m[1][1] = 0;
908	                    layer->matrix.m[1][2] = disp_refr->ver_res;
909	                    break;
910	
911	                case LV_DISPLAY_ROTATION_180:
912	                    /**
913	                     * lv_matrix_rotate(&layer->matrix, 180);
914	                     * lv_matrix_translate(&layer->matrix, -disp_refr->hor_res, -disp_refr->ver_res);
915	                     */
916	                    layer->matrix.m[0][0] = -1;
917	                    layer->matrix.m[0][1] = 0;
918	                    layer->matrix.m[0][2] = disp_refr->hor_res;
919	                    layer->matrix.m[1][0] = 0;
920	                    layer->matrix.m[1][1] = -1;
921	                    layer->matrix.m[1][2] = disp_refr->ver_res;
922	                    break;

734	    }
735	
736	    if(act_scr) lv_obj_send_event(act_scr, LV_EVENT_SCREEN_UNLOAD_START, NULL);
737	
738	    lv_anim_start(&a_new);
739	    if(act_scr) lv_anim_start(&a_old);
740	}
