50	    echo "FLASH_DANGER_ERASE_HANG on attempt $i (erase started but never passed — re-flash)"
51	    grep -E 'Gotten Bus|Begin EraseFlash|Erasing Flash' "$log" | tail -5
52	    break
53	  fi
54	
55	  # No "Gotten Bus" -> safe handshake timeout (Flash untouched) -> retry.
56	  echo "attempt $i: handshake timeout (safe), retrying"
57	  tail -2 "$log" | sed 's/^/  /'
58	done
59	
60	echo "FLASH_LOOP_END"
