337	int particle_flow_view_init(void)
338	{
339	  if (s_pf.initialized) return 0;
340	
341	  memset(&s_pf, 0, sizeof(s_pf));
342	  s_pf.state = PARTICLE_STATE_IDLE;
343	
344	  s_pf.screen = lv_obj_create(NULL);
345	  if (!s_pf.screen) return -ENOMEM;
346	  lv_obj_set_style_bg_color(s_pf.screen, lv_color_hex(UI_PAL_BG), 0);
347	  lv_obj_set_style_bg_opa(s_pf.screen, LV_OPA_COVER, 0);
348	  lv_obj_set_style_text_font(s_pf.screen, &lv_font_misans_16_cjk, 0);
349	
350	  /* Display geometry: center + round bound. */
351	  lv_display_t *disp = lv_display_get_default();
352	  int32_t h = lv_display_get_horizontal_resolution(disp);
353	  int32_t v = lv_display_get_vertical_resolution(disp);
354	  s_pf.cx = h / 2;
355	  s_pf.cy = v / 2;
356	  int32_t half = (h < v ? h : v) / 2;
357	  /* Inscribe the particle travel bound INSIDE the round face: subtract the
358	   * particle radius (PARTICLE_DIAM/2) so a particle centred at the bound has
359	   * its outer edge on the circle, never spilling into the bezel. */
360	  s_pf.R = (half > 8) ? (half - 8 - PARTICLE_DIAM / 2) : 8;
361	  s_pf.R_sq = s_pf.R * s_pf.R;
362	
363	  /* Faint guide ring (shared motif with pet_status_view): a barely-there dark
364	   * boundary circle.  The particles + core already carry the state color, so
365	   * the ring itself stays subtle rather than competing with them. */
366	  s_pf.guide_ring = lv_arc_create(s_pf.screen);
367	  if (s_pf.guide_ring)
368	    {
369	      lv_obj_set_size(s_pf.guide_ring, GUIDE_RING_DIAM, GUIDE_RING_DIAM);
370	      lv_obj_center(s_pf.guide_ring);
371	      lv_arc_set_bg_angles(s_pf.guide_ring, 0, 360);
372	      lv_arc_set_angles(s_pf.guide_ring, 0, 360);
373	      lv_obj_set_style_arc_width(s_pf.guide_ring, 2, LV_PART_MAIN);
374	      lv_obj_set_style_arc_width(s_pf.guide_ring, 0, LV_PART_INDICATOR);
375	      lv_obj_set_style_arc_color(s_pf.guide_ring, lv_color_hex(UI_PAL_TRACK), LV_PART_MAIN);
376	      lv_obj_set_style_bg_opa(s_pf.guide_ring, LV_OPA_TRANSP, LV_PART_KNOB);
377	      lv_obj_remove_flag(s_pf.guide_ring, LV_OBJ_FLAG_CLICKABLE);
378	    }
379	
380	  /* Central pulsing core. */
381	  s_pf.core = make_circle(s_pf.screen, CORE_DIAM, UI_PAL_IDLE, LV_OPA_80);
382	
383	  /* Particles — scattered initially within the disc. */
384	  uint32_t seed = 0x1234abcd;
385	  for (int i = 0; i < N_PARTICLES; i++)
386	    {
387	      /* place around a ring with jitter so they don't overlap the core */
388	      int32_t ang = (i * 360 / N_PARTICLES) % 360;
389	      /* cheap sin/cos via a 4-bin triangle so no math.h: */
390	      int32_t qx = (ang < 90) ? ang : (ang < 270) ? (180 - ang) : (ang - 360);
391	      int32_t qy = ((ang + 270) % 360);
392	      qy = (qy < 90) ? qy : (qy < 270) ? (180 - qy) : (qy - 360);
393	      /* qx, qy ∈ [-90, 90] → normalize to [-1, 1] */
394	      int32_t rx = (qx * 0x7fff) / 90;
395	      int32_t ry = (qy * 0x7fff) / 90;
396	      int32_t radius = s_pf.R * 2 / 3;
397	      int32_t jitter = (lcg_next(&seed) * radius) / 16384;
398	      int32_t rr = radius + (jitter / 4);
399	      if (rr < 6) rr = 6;
400	      if (rr > s_pf.R - 2) rr = s_pf.R - 2;
401	
402	      s_pf.p[i].x = s_pf.cx + (int32_t)(((int64_t)rx * rr) / 0x7fff);
403	      s_pf.p[i].y = s_pf.cy + (int32_t)(((int64_t)ry * rr) / 0x7fff);
404	      s_pf.p[i].vx = lcg_next(&seed) / 8;   /* small initial velocity */
405	      s_pf.p[i].vy = lcg_next(&seed) / 8;
406	      s_pf.p[i].lcg = seed;
407	
408	      /* Soft particles — 80% opacity recedes them into the near-black field
409	       * (HachimoDock softness) instead of hard neon dots. */
410	      s_pf.particles[i] = make_circle(s_pf.screen, PARTICLE_DIAM,
411	                                       UI_PAL_IDLE, LV_OPA_80);
412	      if (s_pf.particles[i])
413	        {
414	          int32_t prx = s_pf.p[i].x - (PARTICLE_DIAM / 2);
415	          int32_t pry = s_pf.p[i].y - (PARTICLE_DIAM / 2);
416	          lv_obj_set_pos(s_pf.particles[i], prx, pry);
417	          s_pf.p[i].last_rx = prx;
418	          s_pf.p[i].last_ry = pry;
419	        }
420	    }
421	
422	  /* State caption row (dot + text), mirroring pet_status_view's caption so the
423	   * particle page's status text is anchored to a UI block rather than floating
424	   * as a bare label.  Placed low inside the circle, clear of the core/ring. */
425	  {
426	    lv_obj_t *caption = lv_obj_create(s_pf.screen);
427	    if (caption)
428	      {
429	        lv_obj_remove_flag(caption, LV_OBJ_FLAG_SCROLLABLE);
430	        lv_obj_set_size(caption, LV_SIZE_CONTENT, LV_SIZE_CONTENT);
431	        lv_obj_set_style_bg_opa(caption, LV_OPA_TRANSP, 0);
432	        lv_obj_set_style_border_width(caption, 0, 0);
433	        lv_obj_set_style_pad_all(caption, 0, 0);
434	        lv_obj_set_flex_flow(caption, LV_FLEX_FLOW_ROW);
435	        lv_obj_set_flex_align(caption, LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER,
436	                              LV_FLEX_ALIGN_CENTER);
437	        lv_obj_set_style_pad_column(caption, 6, 0);
438	        /* 88 matches pet_status_view's PET_LABEL_DY: the caption (dot+text)
439	         * is 20px tall (MiSans line_height=20), so its top is 88-10=78 below
440	         * center → y=226, clearing the 150px guide ring bottom (y=223) by 3px
441	         * instead of overlapping. */
442	        lv_obj_align(caption, LV_ALIGN_CENTER, 0, 88);
443	
444	        s_pf.status_dot = lv_obj_create(caption);
445	        if (s_pf.status_dot)
446	          {
447	            lv_obj_remove_flag(s_pf.status_dot, LV_OBJ_FLAG_SCROLLABLE);
448	            lv_obj_set_size(s_pf.status_dot, 8, 8);
449	            lv_obj_set_style_radius(s_pf.status_dot, LV_RADIUS_CIRCLE, 0);
450	            lv_obj_set_style_bg_color(s_pf.status_dot, lv_color_hex(UI_PAL_IDLE), 0);
451	            lv_obj_set_style_bg_opa(s_pf.status_dot, LV_OPA_COVER, 0);
452	            lv_obj_set_style_border_width(s_pf.status_dot, 0, 0);
453	            lv_obj_set_style_pad_all(s_pf.status_dot, 0, 0);
454	          }
455	
456	        s_pf.label = lv_label_create(caption);
457	        if (s_pf.label)
458	          {
459	            lv_label_set_text(s_pf.label, s_state_text[PARTICLE_STATE_IDLE]);
460	            lv_obj_set_style_text_color(s_pf.label, lv_color_hex(UI_PAL_TEXT_DIM), 0);
461	            lv_obj_set_style_text_font(s_pf.label, &lv_font_misans_16_cjk, 0);
462	          }
463	      }
464	  }
465	
466	  /* Physics timer — runs on the LVGL thread, so widget mutation is safe. */
467	  s_pf.timer = lv_timer_create(timer_cb, TICK_MS, NULL);
468	  if (s_pf.timer)
469	    {
470	      lv_timer_set_repeat_count(s_pf.timer, -1);
471	    }
472	
473	  s_pf.initialized = true;
474	  syslog(LOG_INFO, "[%s] init OK (圆屏粒子流, %d 粒子, disp %dx%d R=%d)\n",
475	         TAG, N_PARTICLES, (int)h, (int)v, (int)s_pf.R);
476	  return 0;
477	}
