155	/* Breathing: sprite opacity pulses (IDLE). value 0..100. */
156	static void breathe_cb(void *obj, int32_t v)
157	{
158	  lv_obj_t *o = (lv_obj_t *)obj;
159	  /* 100% → 255, 0% → 190 (gentle). */
160	  lv_obj_set_style_opa(o, LV_OPA_COVER - (v * (LV_OPA_COVER - 190)) / 100, 0);
161	}
162	
163	/* Float: gentle vertical bob (IDLE, layered with the opacity breathe so the
164	 * idle pet feels alive rather than a static icon). value 0..100. */
165	static void float_cb(void *obj, int32_t v)
166	{
167	  lv_obj_t *o = (lv_obj_t *)obj;
168	  /* Triangle 0→+2→0→-2→0 across one cycle — a ±2px bob on a 96px sprite. */
169	  int32_t amp;
170	  if (v < 25)      amp = (v * 2) / 25;
171	  else if (v < 50) amp = ((50 - v) * 2) / 25;
172	  else if (v < 75) amp = -((v - 50) * 2) / 25;
173	  else             amp = -((100 - v) * 2) / 25;
174	  lv_obj_set_style_translate_y(o, amp, 0);
175	}
